package com.fincore.fincore.security;
import java.nio.charset.StandardCharsets; import java.util.Date; import javax.crypto.SecretKey; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys;
@Service public class JwtService { private final SecretKey key; private final long expiration; public JwtService(@Value("${app.jwt.secret}") String s,@Value("${app.jwt.expiration-ms}") long e){key=Keys.hmacShaKeyFor(s.getBytes(StandardCharsets.UTF_8));expiration=e;} public String generate(AuthenticatedUser u){var now=new Date();return Jwts.builder().subject(u.getUsername()).issuedAt(now).expiration(new Date(now.getTime()+expiration)).signWith(key).compact();} public String username(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getSubject();} public boolean valid(String token){try{Jwts.parser().verifyWith(key).build().parseSignedClaims(token);return true;}catch(JwtException|IllegalArgumentException e){return false;}} }
